/* cppi::9c0456139f74e9f7fdfb1a7b84eec914eb72a787f78dae3f059d618395af32f5 */
with cslxhis as(
    with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from ( select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2 )
    ) --select * from cslDates
    select his.* from df_trusted_prod.mds_csl_daily_history his
        join cslDates cDates on his.business_date = date(cDates.previous_business_dt)
        ORDER BY his.id_cppibsec
    )
    select distinct(business_date) from cslxhis

/* cppi::cc829af3ac86385353c1a5325e054746f8851701a5b89343729a3fb7fb9fa43f */
with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from (
        select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2
    )
    ), cslxhis as(
    select *
    from df_trusted_prod.mds_csl_daily_history his
        join cslDates cDates on his.business_date = cDates.business_dt
        where his.business_date = cDates.business_dt or his.business_date = cDates.previous_business_dt
        ORDER BY his.business_date
    ), RankedData AS (
    SELECT *,
        ROW_NUMBER() OVER (PARTITION BY id_cppibsec ORDER BY business_date DESC) AS rn
    from cslxhis
    )

select * from RankedData

